-- Replace generic math stems with short, topic-specific applications.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en,
    quiz_fil=v.quiz_fil,
    explanation_en=v.explanation_en,
    explanation_fil=v.explanation_fil,
    options=v.options::jsonb
FROM (VALUES
 ('starter-mathematics-prime', $$A student lists the positive factors of 13. Why is 13 prime?$$, $$Inilista ng mag-aaral ang mga positibong factor ng 13. Bakit prime ang 13?$$, $$A prime number has exactly two positive factors: 1 and itself.$$ , $$Dalawa lamang ang positibong factor ng prime number: 1 at ang sarili nito.$$ , $$[{"en":"Its only positive factors are 1 and 13","fil":"1 at 13 lamang ang positibong factor nito","correct":true},{"en":"It is divisible by every odd number","fil":"Nahahati ito sa lahat ng odd number","correct":false},{"en":"It has exactly three factors","fil":"Mayroon itong eksaktong tatlong factor","correct":false},{"en":"It is a multiple of 10","fil":"Multiple ito ng 10","correct":false}]$$),
 ('starter-mathematics-composite', $$The number 18 has factors 1, 2, 3, 6, 9, and 18. How is it classified?$$, $$May mga factor na 1, 2, 3, 6, 9, at 18 ang bilang na 18. Paano ito inuuri?$$, $$A composite number has more than two positive factors.$$ , $$Higit sa dalawa ang positibong factor ng composite number.$$ , $$[{"en":"Composite","fil":"Composite","correct":true},{"en":"Prime","fil":"Prime","correct":false},{"en":"Irrational","fil":"Irrational","correct":false},{"en":"A unit fraction","fil":"Unit fraction","correct":false}]$$),
 ('starter-mathematics-fraction', $$A pizza is cut into 8 equal slices and 3 are eaten. What fraction of the pizza was eaten?$$, $$Hinati sa 8 magkakapantay na hiwa ang pizza at kinain ang 3. Anong bahagi ng pizza ang nakain?$$, $$A fraction represents part of a whole; 3 of 8 equal slices is 3/8.$$ , $$Kinakatawan ng fraction ang bahagi ng kabuuan; 3 sa 8 pantay na hiwa ay 3/8.$$ , $$[{"en":"3/8","fil":"3/8","correct":true},{"en":"8/3","fil":"8/3","correct":false},{"en":"3/5","fil":"3/5","correct":false},{"en":"5/8","fil":"5/8","correct":false}]$$),
 ('starter-mathematics-equivalent-fractions', $$A recipe uses 2/3 cup of flour. Which fraction names the same amount?$$, $$Gumagamit ang recipe ng 2/3 tasa ng harina. Aling fraction ang katumbas na dami?$$, $$Multiplying numerator and denominator by the same nonzero number gives an equivalent fraction; 2/3 = 4/6.$$ , $$Magkakatumbas ang fraction kapag minultiply sa parehong di-serong bilang ang numerator at denominator; 2/3 = 4/6.$$ , $$[{"en":"4/6","fil":"4/6","correct":true},{"en":"3/4","fil":"3/4","correct":false},{"en":"2/6","fil":"2/6","correct":false},{"en":"6/4","fil":"6/4","correct":false}]$$),
 ('starter-mathematics-ratio', $$A class has 3 red balls for every 2 blue balls. What is the ratio of red to blue?$$, $$May 3 pulang bola sa bawat 2 asul na bola sa klase. Ano ang ratio ng pula sa asul?$$, $$A ratio compares quantities in the stated order, so red to blue is 3:2.$$ , $$Inihahambing ng ratio ang dami ayon sa pagkakasunod na binanggit, kaya 3:2 ang pula sa asul.$$ , $$[{"en":"3:2","fil":"3:2","correct":true},{"en":"2:3","fil":"2:3","correct":false},{"en":"3:5","fil":"3:5","correct":false},{"en":"5:2","fil":"5:2","correct":false}]$$),
 ('starter-mathematics-unit-rate', $$A 12-kilometer trip takes 3 hours at a steady pace. What is the unit rate?$$, $$Tumatagal ng 3 oras ang 12-kilometrong biyahe sa tuloy-tuloy na bilis. Ano ang unit rate?$$, $$A unit rate is the amount per one unit; 12 ÷ 3 = 4 kilometers per hour.$$ , $$Dami sa bawat isang yunit ang unit rate; 12 ÷ 3 = 4 kilometro kada oras.$$ , $$[{"en":"4 kilometers per hour","fil":"4 kilometro kada oras","correct":true},{"en":"9 kilometers per hour","fil":"9 kilometro kada oras","correct":false},{"en":"15 kilometers per hour","fil":"15 kilometro kada oras","correct":false},{"en":"36 kilometers per hour","fil":"36 kilometro kada oras","correct":false}]$$),
 ('starter-mathematics-percent', $$A learner answers 25 out of 100 questions correctly. What percent is correct?$$, $$Nasagot nang tama ng mag-aaral ang 25 sa 100 tanong. Ilang porsiyento ang tama?$$, $$Percent means per hundred, so 25 out of 100 is 25 percent.$$ , $$Nangangahulugan ang percent na kada isang daan, kaya 25 porsiyento ang 25 sa 100.$$ , $$[{"en":"25%","fil":"25%","correct":true},{"en":"2.5%","fil":"2.5%","correct":false},{"en":"40%","fil":"40%","correct":false},{"en":"75%","fil":"75%","correct":false}]$$),
 ('starter-mathematics-integers', $$The temperature is 4°C and then falls by 7°C. What is the new temperature?$$, $$Nasa 4°C ang temperatura at bumaba pa ito nang 7°C. Ano na ang bagong temperatura?$$, $$A drop of 7 from 4 is 4 − 7 = −3, which is an integer.$$ , $$Ang pagbawas ng 7 mula sa 4 ay 4 − 7 = −3, isang integer.$$ , $$[{"en":"−3°C","fil":"−3°C","correct":true},{"en":"3°C","fil":"3°C","correct":false},{"en":"11°C","fil":"11°C","correct":false},{"en":"−11°C","fil":"−11°C","correct":false}]$$),
 ('starter-mathematics-rational', $$Which number can be written as a ratio of two integers?$$, $$Aling bilang ang maisusulat bilang ratio ng dalawang integer?$$, $$A rational number can be written as a/b for integers a and b, with b not zero; 3/4 is rational.$$ , $$Maisusulat ang rational number bilang a/b gamit ang mga integer at di-serong b; rational ang 3/4.$$ , $$[{"en":"3/4","fil":"3/4","correct":true},{"en":"√2","fil":"√2","correct":false},{"en":"π","fil":"π","correct":false},{"en":"A nonrepeating, nonterminating decimal only","fil":"Di-umuulit at di-nagtatapos na decimal lamang","correct":false}]$$),
 ('starter-mathematics-mean', $$A learner’s scores are 4, 6, and 8. What is the mean score?$$, $$4, 6, at 8 ang mga marka ng mag-aaral. Ano ang mean na marka?$$, $$The mean is the sum divided by the count: (4 + 6 + 8) ÷ 3 = 6.$$ , $$Ang mean ay kabuuan na hinati sa dami: (4 + 6 + 8) ÷ 3 = 6.$$ , $$[{"en":"6","fil":"6","correct":true},{"en":"4","fil":"4","correct":false},{"en":"8","fil":"8","correct":false},{"en":"18","fil":"18","correct":false}]$$),
 ('starter-mathematics-median', $$The ordered data are 2, 5, and 9. What is the median?$$, $$2, 5, at 9 ang nakaayos na datos. Ano ang median?$$, $$The median is the middle value in ordered data; here it is 5.$$ , $$Ang median ang nasa gitna ng nakaayos na datos; 5 ito sa halimbawang ito.$$ , $$[{"en":"5","fil":"5","correct":true},{"en":"2","fil":"2","correct":false},{"en":"9","fil":"9","correct":false},{"en":"16","fil":"16","correct":false}]$$),
 ('starter-mathematics-mode', $$In the data set 2, 3, 3, 4, which value occurs most often?$$, $$Sa datos na 2, 3, 3, 4, aling halaga ang pinakamadalas lumitaw?$$, $$The mode is the value that appears most often; 3 appears twice.$$ , $$Ang mode ang halagang pinakamadalas lumitaw; dalawang beses lumitaw ang 3.$$ , $$[{"en":"3","fil":"3","correct":true},{"en":"2","fil":"2","correct":false},{"en":"4","fil":"4","correct":false},{"en":"12","fil":"12","correct":false}]$$),
 ('starter-mathematics-range', $$The highest score is 92 and the lowest is 67. What is the range?$$, $$92 ang pinakamataas na marka at 67 ang pinakamababa. Ano ang range?$$, $$The range is maximum minus minimum: 92 − 67 = 25.$$ , $$Ang range ay maximum na binawasan ng minimum: 92 − 67 = 25.$$ , $$[{"en":"25","fil":"25","correct":true},{"en":"159","fil":"159","correct":false},{"en":"29","fil":"29","correct":false},{"en":"67","fil":"67","correct":false}]$$),
 ('starter-mathematics-probability', $$A fair coin is flipped once. What is the probability of getting heads?$$, $$Ihahagis nang isang beses ang patas na barya. Ano ang posibilidad na lumabas ang ulo?$$, $$A fair coin has two equally likely outcomes, so the probability of heads is 1/2.$$ , $$Dalawa ang pantay na posibleng kalabasan ng patas na barya, kaya 1/2 ang posibilidad ng ulo.$$ , $$[{"en":"1/2","fil":"1/2","correct":true},{"en":"1/4","fil":"1/4","correct":false},{"en":"1","fil":"1","correct":false},{"en":"2","fil":"2","correct":false}]$$),
 ('starter-mathematics-circumference', $$A circle has radius 5 cm. Which expression gives its circumference?$$, $$May radius na 5 cm ang bilog. Aling expression ang nagbibigay ng circumference nito?$$, $$Circumference is 2πr, so for r = 5 cm it is 10π cm.$$ , $$2πr ang circumference, kaya 10π cm ito kapag 5 cm ang radius.$$ , $$[{"en":"10π cm","fil":"10π cm","correct":true},{"en":"5π cm","fil":"5π cm","correct":false},{"en":"25π cm","fil":"25π cm","correct":false},{"en":"10 cm²","fil":"10 cm²","correct":false}]$$),
 ('starter-mathematics-rectangle-area', $$A rectangular garden is 8 m long and 3 m wide. What is its area?$$, $$8 m ang haba at 3 m ang lapad ng parihabang hardin. Ano ang lawak nito?$$, $$The area of a rectangle is length times width: 8 × 3 = 24 square meters.$$ , $$Haba na minultiply sa lapad ang lawak ng parihaba: 8 × 3 = 24 metro kuwadrado.$$ , $$[{"en":"24 m²","fil":"24 m²","correct":true},{"en":"22 m²","fil":"22 m²","correct":false},{"en":"11 m²","fil":"11 m²","correct":false},{"en":"24 m","fil":"24 m","correct":false}]$$),
 ('starter-mathematics-triangle-angle', $$Two angles of a triangle measure 55° and 65°. What is the third angle?$$, $$55° at 65° ang dalawang anggulo ng tatsulok. Ano ang ikatlong anggulo?$$, $$Triangle angles total 180°; 180° − 55° − 65° = 60°.$$ , $$180° ang kabuuan ng mga anggulo ng tatsulok; 180° − 55° − 65° = 60°.$$ , $$[{"en":"60°","fil":"60°","correct":true},{"en":"50°","fil":"50°","correct":false},{"en":"65°","fil":"65°","correct":false},{"en":"120°","fil":"120°","correct":false}]$$),
 ('starter-mathematics-complementary', $$One angle measures 35°. What is its complementary angle?$$, $$35° ang sukat ng isang anggulo. Ano ang complementary angle nito?$$, $$Complementary angles total 90°, so 90° − 35° = 55°.$$ , $$90° ang kabuuan ng complementary angles, kaya 90° − 35° = 55°.$$ , $$[{"en":"55°","fil":"55°","correct":true},{"en":"145°","fil":"145°","correct":false},{"en":"35°","fil":"35°","correct":false},{"en":"90°","fil":"90°","correct":false}]$$),
 ('starter-mathematics-supplementary', $$One angle on a straight line measures 118°. What is the supplementary angle beside it?$$, $$118° ang isang anggulo sa tuwid na linya. Ano ang katabing supplementary angle nito?$$, $$Supplementary angles total 180°, so 180° − 118° = 62°.$$ , $$180° ang kabuuan ng supplementary angles, kaya 180° − 118° = 62°.$$ , $$[{"en":"62°","fil":"62°","correct":true},{"en":"72°","fil":"72°","correct":false},{"en":"118°","fil":"118°","correct":false},{"en":"298°","fil":"298°","correct":false}]$$),
 ('starter-mathematics-order-operations', $$Evaluate 3 + 4 × 2 using the usual order of operations.$$ , $$Kuwentahin ang 3 + 4 × 2 gamit ang karaniwang pagkakasunod-sunod ng operasyon.$$ , $$Multiply before adding: 3 + (4 × 2) = 11.$$ , $$Unahin ang multiplication bago ang addition: 3 + (4 × 2) = 11.$$ , $$[{"en":"11","fil":"11","correct":true},{"en":"14","fil":"14","correct":false},{"en":"10","fil":"10","correct":false},{"en":"24","fil":"24","correct":false}]$$),
 ('starter-mathematics-proportion', $$A map uses 4 cm for 8 km. At the same scale, how many kilometers does 3 cm represent?$$, $$Kumakatawan ang 4 cm sa mapa sa 8 km. Sa parehong scale, ilang kilometro ang katumbas ng 3 cm?$$, $$The scale is 2 km per centimeter, so 3 cm represents 6 km.$$ , $$2 km kada sentimetro ang scale, kaya 6 km ang katumbas ng 3 cm.$$ , $$[{"en":"6 km","fil":"6 km","correct":true},{"en":"4 km","fil":"4 km","correct":false},{"en":"8 km","fil":"8 km","correct":false},{"en":"24 km","fil":"24 km","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,explanation_en,explanation_fil,options)
WHERE c.content_key=v.content_key;
